<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Opening secure payment · MediServe</title><style>body{margin:0;min-height:100vh;display:grid;place-items:center;background:#f5faf8;color:#18332c;font:16px/1.5 system-ui,sans-serif}.panel{width:min(430px,calc(100% - 32px));padding:30px;text-align:center;background:#fff;border:1px solid #e6eeeb;border-radius:16px}.spinner{width:34px;height:34px;margin:0 auto 16px;border:3px solid #d8ebe1;border-top-color:#087f5b;border-radius:50%;animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}p{color:#70817c}</style><script src="https://sdk.cashfree.com/js/v3/cashfree.js"></script></head><body><main class="panel"><div class="spinner"></div><strong>Opening Cashfree secure checkout</strong><p>Please wait while we connect you to the sandbox payment page.</p><noscript>JavaScript is required to open secure checkout.</noscript></main><script>const cashfree=Cashfree({mode:@json($mode)});cashfree.checkout({paymentSessionId:@json($paymentSessionId),redirectTarget:"_self"}).then(result=>{if(result&&result.error){document.querySelector('.panel p').textContent=result.error.message||'Could not open checkout. Return to the previous page and try again.'}});</script></body></html>
